package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsFile 是仓库级低库存阈值配置，位于模块根 config/ 下。
const thresholdsFile = "config/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 仓库在 config/thresholds.json 里配了自己的阈值就用它，否则回退 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	thresholds, ok := readThresholds()
	if !ok {
		return DefaultLowStockThreshold
	}
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}

// readThresholds 读取并解析 config/thresholds.json。
//
// 文件不存在、读不出来、或内容不是 JSON 对象时返回 ok=false，由调用方回退默认值。
func readThresholds() (map[string]int, bool) {
	path, ok := findThresholdsFile()
	if !ok {
		return nil, false
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, false
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil || thresholds == nil {
		return nil, false
	}
	return thresholds, true
}

// findThresholdsFile 从当前工作目录向上找到 config/thresholds.json。
//
// go test 以包目录为工作目录，向上找才能命中模块根的 config/。
func findThresholdsFile() (string, bool) {
	dir, err := os.Getwd()
	if err != nil {
		return "", false
	}
